"},{"path":"rules.py","text":"def ledger(data, sequence_first, discounted):
    def rounded(n, mode):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data.get("rounding", "floor")
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = rounded(base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def resolve(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best = None

    def visit(assign, limits, graph):
        nonlocal best
        # Validate all constraints accumulated so far.
        for name, (lo, hi) in limits.items():
            if name in assign and not lo <= assign[name] <= hi:
                return
        pending = [n for n in limits if n not in assign]
        if not pending:
            # Reject directed cycles in the selected dependency graph.
            active, done = set(), set()
            def acyclic(node):
                if node in active:
                    return False
                if node in done:
                    return True
                active.add(node)
                if any(not acyclic(child) for child in graph.get(node, ())):
                    return False
                active.remove(node)
                done.add(node)
                return True
            if not all(acyclic(n) for n in assign):
                return
            vector = tuple(assign.get(n, -1) for n in names)
            if best is None or vector < best[0]:
                best = (vector, dict(assign))
            return

        name = min(pending)
        lo, hi = limits[name]
        versions = sorted(row["version"] for row in packages[name]
                          if lo <= row["version"] <= hi
                          and row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        for version in versions:
            row = next(r for r in packages[name] if r["version"] == version)
            new_assign = dict(assign)
            new_assign[name] = version
            new_limits = dict(limits)
            new_graph = {k: list(v) for k, v in graph.items()}
            deps = [d for d in row.get("deps", [])
                    if not d.get("feature") or d["feature"] in features]
            new_graph[name] = [d["name"] for d in deps]
            valid = True
            for dep in deps:
                child = dep["name"]
                low, high = dep["min"], dep["max"]
                if child in new_limits:
                    old_low, old_high = new_limits[child]
                    low, high = max(low, old_low), min(high, old_high)
                if low > high:
                    valid = False
                    break
                new_limits[child] = (low, high)
                if child in new_assign and not low <= new_assign[child] <= high:
                    valid = False
                    break
            if valid:
                visit(new_assign, new_limits, new_graph)

    limits = {name: (bounds[0], bounds[1]) for name, bounds in roots.items()}
    visit({}, limits, {})
    return {"versions": best[1]} if best is not None else {"error": "unsatisfiable"}


def select_jobs(data):
    from itertools import combinations
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [j for j in jobs if j["id"] not in blocked]
    best_value, best_ids = None, None
    for subset in combinations(options, k):
        ids = [j["id"] for j in subset]
        idset = set(ids)
        if not mandatory <= idset:
            continue
        counts = {}
        valid = True
        for i, job in enumerate(subset):
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
            for other in subset[:i]:
                if max(job["start"], other["start"]) < min(job["end"], other["end"]):
                    valid = False
                    break
            if not valid:
                break
        if not valid:
            continue
        for group, (low, high) in quotas.items():
            if not low <= counts.get(group, 0) <= high:
                valid = False
                break
        if not valid:
            continue
        value = sum(j["value"] for j in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def routes(data):
    import heapq
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    initial_mask = bits.get(source, 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start = data["start"]
    dist = {(source, initial_mask, 0): start}
    heap = [(start, source, initial_mask, 0)]
    while heap:
        time, node, mask, used = heapq.heappop(heap)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == target and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, new_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                new_mask = mask | bits.get(dest, 0)
                new_state = (dest, new_mask, new_used)
                if arrival < dist.get(new_state, float("inf")):
                    dist[new_state] = arrival
                    heapq.heappush(heap, (arrival, dest, new_mask, new_used))
    return {"arrival": None}


